j:jelly.g2:evaluate:
var isHidden = true;
var view  = jelly.sysparm_view || '';
if (view.indexOf('sys_popup') == 0 )
	isHidden = true;
//Check this is not a new UI record
else if(current.isNewRecord()){
	isHidden = true;
}
//Check Gen AI plugin is active
else if (GlidePluginManager.isActive('sn_km_gen_ai')) {
	var answer = new global.GlobalKnowledgeUtil().isArticleModified(current.sys_id);
	isHidden = (answer != 'false');
}
isHidden;
